import React, { useEffect } from 'react' 
import { useCart } from 'react-use-cart'; 
import Movies from '../Data/Movies.json'

function MovieDetail() {
    const { addItem } = useCart(); 
    const currentMovie = Movies[2]; 

    return (
        <div>
            <div className='MovieDetail-home '>
                <div className="container-lg">
                    <div className="row">
                        
                        <div className="col-md-6 text-light d-flex flex-column justify-content-center" >
                            <h2 className='fst-italic fw-bolder mb-3'>{currentMovie.title}</h2>
                            <p className='text-secondary fw-semibold fs-5'>{currentMovie.description}</p>
                            <span className='fw-bolder fs-5 text-warning ' >duration: {currentMovie.duration}</span>
                            <br />
                            <span className='fw-bold fs-5 text-danger '>price: ${currentMovie.price}</span>
                            <br />
                            
                            <div className="d-flex justify-content-center align-items-center gap-2 mb-3 px-4">
                                <button
                                    onClick={() => {
                                        addItem(currentMovie); 
                                    }}
                                    className='btn btn-success fw-semibold fs-5 flex-grow-1 py-2'
                                >
                                    buy ticket
                                </button>
                            </div>                    
                        </div>

                        <div className="col-md-6 col-sm-12 d-flex justify-content-end">
                            <img 
                                src={`/${currentMovie.img}`} 
                                style={{ width: "80%", borderRadius: "10px", objectFit: "cover" }} 
                                alt={currentMovie.title}
                            />
                        </div>

                    </div>
                </div>
            </div>
        </div>
    )
}

export default MovieDetail;
