import React from 'react'
import { useParams, Link } from 'react-router-dom'
import { useCart } from 'react-use-cart' 
import Movies from '../Data/Movies.json' 

function AllSingleProduct() {
    const { id } = useParams();
    const { addItem } = useCart();

    const movie = Movies.find(m => m.id === Number(id));

    if (!movie) {
        return (
            <div className="container my-5 text-center text-light">
                <h2>🎬 Movie Not Found!</h2>
                <Link to="/movie" className="btn btn-danger mt-3">Back to Movies</Link>
            </div>
        );
    }

    return (
        <div>
            <div className="container my-5 text-light" >
                <div className="mb-4">
                    <Link to="/movie" className="btn btn-outline-secondary text-light fw-semibold">
                        ← Back to Movies
                    </Link>
                </div>

                <div className="row g-5 align-items-center bg-dark p-4 rounded shadow-lg">

                    <div className="col-md-4 text-center">
                        <img
                            src={`/${movie.img}`}
                            alt={movie.title}
                            className="img-fluid rounded shadow"
                            style={{ maxHeight: '500px', objectFit: 'cover' }}
                        />
                    </div>

                    <div className="col-md-8">
                        <h1 className="fw-bold fst-italic text-success mb-3">{movie.title}</h1>

                        <div className="mb-4">
                            {movie.genre && movie.genre.map((g, index) => (
                                <span key={index} className="badge bg-secondary me-2 fs-6">
                                    {g}
                                </span>
                            ))}
                        </div>

                        <h4 className="fw-bold text-secondary">Storyline:</h4>
                        <p className="fs-5 text-light-50 lh-base mb-4">{movie.description}</p>

                        <div className="row g-3 mb-4 bg-black bg-opacity-25 p-3 rounded">
                            <div className="col-sm-6">
                                <span className="text-secondary fw-bold">⏱️ Duration:</span>
                                <span className="ms-2 fs-5 fw-semibold">{movie.duration}</span>
                            </div>
                            <div className="col-sm-6">
                                <span className="text-secondary fw-bold">💰 Ticket Price:</span>
                                <span className="ms-2 fs-5 fw-bold text-success">${movie.price}</span>
                            </div>
                            {movie.rating && (
                                <div className="col-sm-6">
                                    <span className="text-secondary fw-bold">⭐ Rating:</span>
                                    <span className="ms-2 fs-5 fw-semibold text-warning">{movie.rating} / 10</span>
                                </div>
                            )}
                        </div>

                        <div className="d-flex gap-3 mt-4">
                            <button
                                onClick={() => {
                                    addItem(movie);
                                }}
                                className='btn btn-success text-light fs-4 rounded-3 fw-semibold flex-grow-1 py-2'
                            >
                                Buy Ticket
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default AllSingleProduct;
