import React, { useState, useEffect } from 'react' 
import { Link } from 'react-router-dom'
import Movies from '../Data/Movies.json'
import { useCart } from 'react-use-cart';

function Star() {
    const { addItem } = useCart();
    const [selectedStars, setSelectedStars] = useState("All");

    const [favorites, setFavorites] = useState(() => {
        const saved = localStorage.getItem("myFavs");
        return saved ? JSON.parse(saved) : [];
    });

    useEffect(() => {
        localStorage.setItem("myFavs", JSON.stringify(favorites));
    }, [favorites]);

    const toggleFavorite = (movie) => {
        if (favorites.some(fav => fav.id === movie.id)) {
            setFavorites(favorites.filter(fav => fav.id !== movie.id));
        } else {
            setFavorites([...favorites, movie]);
        }
    };

    const getProcessedMovies = () => {
        const sortedAll = [...Movies].sort((a, b) => b.rating - a.rating);

        if (selectedStars === "All") {
            return sortedAll;
        }

        return sortedAll.filter(movie => {
            if (selectedStars === 1) return movie.rating >= 9.0;
            if (selectedStars === 2) return movie.rating >= 8.0 && movie.rating < 9.0;
            if (selectedStars === 3) return movie.rating >= 7.0 && movie.rating < 8.0;
            return false;
        });
    };

    const finalMovies = getProcessedMovies();

    return (
        <div>
            <div className="container-fluid text-light my-5 star-home">
                <h2 className="text-center mb-5 fw-bold fs-1" style={{ color: "#ffc107", textShadow: "0 0 10px rgba(255,193,7,0.3)" }}>
                    Filter By Ratings ⭐️
                </h2>

                <div className="row ">
                    <div className=' mb-5'>
                        <ul className="navbar-nav d-flex flex-wrap flex-row text-center" >
                            <li className="nav-item col-xxl-3 col-md-6 col-12 mb-5 ">
                                <button onClick={() => setSelectedStars("All")} className={`btn fs-5 fw-bold p-3 rounded-3 ${selectedStars === "All" ? 'btn-warning text-dark' : 'btn-outline-warning'}`}>
                                    All Movies (Sorted)
                                </button>
                            </li>
                            <li className="nav-item col-xxl-3 col-md-6 col-12 mb-5">
                                <button onClick={() => setSelectedStars(1)} className={`btn fs-5 fw-bold p-3 rounded-3 ${selectedStars === 1 ? 'btn-warning text-dark' : 'btn-outline-warning'}`}>
                                    ⭐⭐⭐⭐⭐ Stars (9.0+)
                                </button>
                            </li>
                            <li className="nav-item col-xxl-3 col-md-6 col-12 mb-5 ">
                                <button onClick={() => setSelectedStars(2)} className={`btn fs-5 fw-bold p-3 rounded-3 ${selectedStars === 2 ? 'btn-warning text-dark' : 'btn-outline-warning'}`}>
                                    ⭐⭐⭐⭐ Stars (8.0 - 8.9)
                                </button>
                            </li>
                            <li className="nav-item col-xxl-3 col-md-6  col-12">
                                <button onClick={() => setSelectedStars(3)} className={`btn fs-5 fw-bold p-3 rounded-3 ${selectedStars === 3 || selectedStars === 3 ? 'btn-warning text-dark' : 'btn-outline-warning'}`}>
                                    ⭐⭐⭐ Stars (7.0 - 7.9)
                                </button>
                            </li>
                        </ul>
                    </div>


                    {finalMovies.length === 0 ? (
                        <p className="text-center text-muted fs-4 mt-5">No Movie..!!!</p>
                    ) : (
                        finalMovies.map((movie) => {

                            const isFav = favorites.some(fav => fav.id === movie.id);

                            return (
                                <div key={movie.id} className="col-xxl-4 col-lg-6 col-sm-12 d-flex justify-content-around text-center mb-5 mt-5 star-play">

                                    <div className="card p-1 star-movie" style={{ width: "480px", height: "50rem" }} >
                                        <img src={`/${movie.img}`} className="w-75 my-3 rounded-3" style={{ height: "300px", objectFit: "cover", margin: "auto" }} alt={movie.title} />
                                        <h3 className=" fw-bold fst-italic ">{movie.title}</h3>
                                        <div className='d-flex justify-content-around mb-3 '>
                                            <span className='  text-warning fw-bolder fs-4'> ⭐️ {movie.rating} </span>
                                            <span className=" d-flex align-items-end   text-danger fs-4 fw-bold"> ${movie.price}</span>
                                        </div>

                                        <div >
                                            {movie.genre.map((g, index) => (
                                                <span key={index} className='me-2 p-2 px-lg-3 px-sm-2 px-0  fw-medium text-white rounded-4 bg-secondary '> {g} </span>
                                            ))}
                                        </div>
                                        <p className='lh-lg mt-3 fw-semibold mt-2 fs-5'>showtimes:<br /> everyday {movie.showtimes.join(', ')}</p>
                                        <span className='text-primary fw-bolder fs-5 mb-5'>duration: {movie.duration}</span>

                                        <div className="d-flex justify-content-center align-items-center gap-2 mb-3 px-sm-3 px-1 ">
                                            <button
                                                onClick={() => {
                                                    addItem(movie); }}
                                                className='btn btn-success text-light fs-4 rounded-3 fw-semibold  flex-grow-1 py-2 ' >
                                                Buy Ticket </button>
                                            <Link
                                                to={`/SingleProduct/${movie.id}`}
                                                className='btn btn-dark text-light fs-4 rounded-3 fw-semibold flex-grow-1 py-2 d-flex align-items-center justify-content-center'  >
                                                Details
                                            </Link>

                                            <button
                                                onClick={() => toggleFavorite(movie)}
                                                className={`btn fs-4 border-0 py-2 px-3 ${isFav ? 'btn-danger' : 'btn-outline-danger'}`}
                                                style={{ transition: 'all 0.3s ease' }} >
                                                <i className={isFav ? "fa-solid fa-heart" : "fa-regular fa-heart"}></i>
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>

            </div>
        </div>

    )
}

export default Star;
