import React, { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import { useCart } from 'react-use-cart'
import Movies from '../Data/Movies.json'

function Movie() {
    const { addItem } = useCart();
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedGenre, setSelectedGenre] = useState("All");
    const [currentPage, setCurrentPage] = useState(1);
    const moviesPerPage = 15;

    const [favorites, setFavorites] = useState(() => {
        const saved = localStorage.getItem("myFavs");
        return saved ? JSON.parse(saved) : [];
    });

    useEffect(() => {
        localStorage.setItem("myFavs", JSON.stringify(favorites));
    }, [favorites]);

    const toggleFavorite = (movie) => {
        if (favorites.some(fav => fav.id === movie.id)) {
            setFavorites(favorites.filter(fav => fav.id !== movie.id));
        } else {
            setFavorites([...favorites, movie]);
        }
    };

    const filteredMovies = Movies.filter(movie => {
        const matchesGenre = selectedGenre === "All" || movie.genre.includes(selectedGenre);
        const matchesSearch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesGenre && matchesSearch;
    });

    const indexOfLastMovie = currentPage * moviesPerPage;
    const indexOfFirstMovie = indexOfLastMovie - moviesPerPage;
    const currentMovies = filteredMovies.slice(indexOfFirstMovie, indexOfLastMovie);

    const handleGenreChange = (genre) => {
        setSelectedGenre(genre);
        setCurrentPage(1);
    };

   
    return (
        <div>
            <div className="container-fluid mt-4">
                <div className="row">
                    <div className="col-12 mt-4 px-5">
                        <div className="d-flex w-75 m-auto gap-2 search-movie">
                            <input type="text" className="form-control form-control-lg text-center" placeholder="🔍 Type a movie name..."
                                value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                        </div>
                    </div>

                    <div className='col-md-12 mb-5 w-100 mt-5 '>
                        <ul className="navbar-nav movie-play  d-md-flex flex-md-row justify-content-center mt-3 mt-sm-0 gap-3 gap-md-0">
                            <li className="nav-item   me-sm-4 me-lg-5">
                                <button onClick={() => handleGenreChange("All")} className={`nav-link fs-5 fw-bold p-3 rounded-3 ${selectedGenre === "All" ? 'bg-danger text-white' : 'bg-light text-black'}`}>All</button>
                            </li>
                            <li className="nav-item  me-sm-4 me-lg-5">
                                <button onClick={() => handleGenreChange("Action")} className={`nav-link fs-5 fw-bold p-3 rounded-3 ${selectedGenre === "Action" ? 'bg-danger text-white' : 'bg-light text-black'}`}>Action</button>
                            </li>
                            <li className="nav-item  me-sm-4 me-lg-5">
                                <button onClick={() => handleGenreChange("Adventure")} className={`nav-link fs-5 fw-bold p-3 rounded-3 ${selectedGenre === "Adventure" ? 'bg-danger text-white' : 'bg-light text-black'}`}>Adventure</button>
                            </li>
                            <li className="nav-item   me-sm-4 me-lg-5">
                                <button onClick={() => handleGenreChange("Sci-Fi")} className={`nav-link fs-5 fw-bold p-3 rounded-3 ${selectedGenre === "Sci-Fi" ? 'bg-danger text-white' : 'bg-light text-black'}`}>Sci-Fi</button>
                            </li>
                        </ul>
                    </div>

                    {currentMovies.map((movie) => {
                        const isFav = favorites.some(fav => fav.id === movie.id);

                        return (
                            <div key={movie.id} className="col-xxl-4 col-lg-6 col-sm-12 d-flex justify-content-around text-center mb-5 mt-5 ">
                                <div className="card m-auto MovieCard-enjoy" style={{ width: "480px", height: "48rem" }} >
                                    <img src={`/${movie.img}`} className="w-75 my-3 rounded-3" style={{ height: "350px", objectFit: "cover", margin: "auto" }} alt={movie.title} />
                                    <h3 className=" fw-bold fst-italic ">{movie.title}</h3>
                                    <div className='d-flex justify-content-around mb-3 '>
                                        <span className='  text-warning fw-bolder fs-4'> ⭐️ {movie.rating} </span>
                                        <span className=" d-flex align-items-end   text-danger fs-4 fw-bold"> ${movie.price}</span>

                                    </div>
                                    <div >
                                        {movie.genre.map((g, index) => (
                                            <span key={index} className='me-2 p-2 px-2 fw-medium text-white rounded-4 bg-secondary'> {g} </span>
                                        ))}
                                    </div>
                                    <p className='lh-lg fw-semibold mt-2 fs-5'>showtimes:<br /> everyday {movie.showtimes.join(', ')}</p>
                                    <span className='text-primary fw-bolder mb-5 fs-5'>duration: {movie.duration}</span>



                                    <div className="d-flex justify-content-center align-items-center gap-2 mb-3 px-3">
                                        <button
                                            onClick={() => {
                                                addItem(movie);
                                            }}
                                            className='btn btn-success text-light fs-4 rounded-3 fw-semibold flex-grow-1 py-2'
                                        >
                                            Buy Ticket
                                        </button>

                                        <Link
                                            to={`/SingleProduct/${movie.id}`}
                                            className='btn btn-dark text-light fs-4 rounded-3 fw-semibold flex-grow-1 py-2 d-flex align-items-center justify-content-center'
                                        >
                                            Details
                                        </Link>

                                        <button
                                            onClick={() => toggleFavorite(movie)}
                                            className={`btn fs-4 border-0 py-2 px-3 ${isFav ? 'btn-danger' : 'btn-outline-danger'}`}
                                            style={{ transition: 'all 0.3s ease' }}
                                        >
                                            <i className={isFav ? "fa-solid fa-heart" : "fa-regular fa-heart"}></i>
                                        </button>
                                    </div>

                                </div>
                            </div>
                        )
                    })}

                    <div className='m-auto d-flex justify-content-center mt-5 mb-5'>
                        <ul className="pagination pagination-lg">
                            <li className={`page-item ${currentPage === 1 ? 'active' : ''}`}>
                                <button className="page-link me-2" onClick={() => setCurrentPage(1)}>1</button>
                            </li>
                            {filteredMovies.length > moviesPerPage && (
                                <li className={`page-item ${currentPage === 2 ? 'active' : ''}`}>
                                    <button className="page-link" onClick={() => setCurrentPage(2)}>2</button>
                                </li>
                            )}
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    )
}

export default Movie;
