import React from 'react'
import { Link } from 'react-router-dom' 

function Header() {
    return (
        <div>
            <header className="header-home">
                <div id="carouselExampleControlsNoTouching" className="carousel slide carousel-fade"
                    data-bs-ride="carousel" data-bs-interval="2500" data-bs-pause="false">

                    <div className="header-enjoy carousel-indicators">
                        <button type="button" data-bs-target="#carouselExampleControlsNoTouching"
                            data-bs-slide-to={0} className="active" aria-current="true" aria-label="Slide 1" />
                        <button type="button" data-bs-target="#carouselExampleControlsNoTouching"
                            data-bs-slide-to={1} aria-label="Slide 2" />
                        <button type="button" data-bs-target="#carouselExampleControlsNoTouching"
                            data-bs-slide-to={2} aria-label="Slide 3" />
                        <button type="button" data-bs-target="#carouselExampleControlsNoTouching"
                            data-bs-slide-to={3} aria-label="Slide 4" />
                        <button type="button" data-bs-target="#carouselExampleControlsNoTouching"
                            data-bs-slide-to={4} aria-label="Slide 5" />
                    </div>

                    <div className="carousel-inner">

                        <div className="carousel-item active">
                            <img src="/img/carousel1.jpe" className="d-block w-100" />

                            <div className="position-absolute top-50 end-50 carousel-caption p-2 p-md-3">
                                <h5 className="fw-bold text-white mx-2 mx-md-5 mb-3 mb-md-5 fs-1 text-start">Spider-Man: Brand New Day</h5>
                                {/* 🟢 2. ربط زر More بمسار الأفلام (تأكد من المسار الصحيح لديك، إذا كان '/' أو '/movies') */}
                                <Link to="/Movie" className="text-decoration-none d-block w-75 me-2 me-md-5">
                                    <button className="fw-bolder btn btn-danger w-100 py-1 py-md-2 fs-6 fs-md-5">More</button>
                                </Link>
                            </div>
                        </div>

                        <div className="carousel-item ">
                            <img src="/img/carousel2.jpg" className="d-block w-100" />

                            <div className="position-absolute top-50 end-50 carousel-caption p-2 p-md-3">
                                <h5 className="fw-bold text-white mx-2 mx-md-5 mb-3 mb-md-5 fs-1 fs-md-1 text-start">The Odyssey</h5>
                                <Link to="/Movie" className="text-decoration-none d-block w-75 me-2 me-md-5">
                                    <button className="fw-bolder btn btn-danger w-100 py-1 py-md-2 fs-6 fs-md-5">More</button>
                                </Link>
                            </div>
                        </div>

                        <div className="carousel-item position-relative">
                            <img src="/img/carousel3.jpe" className="d-block w-100" />
                            <div className="position-absolute top-50 end-50 carousel-caption p-2 p-md-3">
                                <h5 className="fw-bold text-white mx-2 mx-md-5 mb-3 mb-md-5 fs-1 fs-md-1 text-start">Avatar: Fire and Ash</h5>
                                <Link to="/Movie" className="text-decoration-none d-block w-75 me-2 me-md-5">
                                    <button className="fw-bolder btn btn-danger w-100 py-1 py-md-2 fs-6 fs-md-5">More</button>
                                </Link>
                            </div>
                        </div>

                        <div className="carousel-item position-relative">
                            <img src="/img/carousel4.jpe" className="d-block w-100" />
                            <div className="position-absolute top-50 mb-sm-5 end-50 carousel-caption p-2 p-md-3">
                                <h5 className="fw-bold text-white mx-2 mx-md-5 mb-3 mb-md-5 fs-1 fs-md-1 text-start">Inception </h5>
                                <Link to="/Movie" className="text-decoration-none d-block w-75 me-2 me-md-5">
                                    <button className="fw-bold btn btn-danger w-100 py-1 py-md-2 fs-6 fs-md-5">More</button>
                                </Link>
                            </div>
                        </div>

                        <div className="carousel-item position-relative">
                            <img src="/img/carousel5.jpe" className="d-block w-100" />
                            <div className="position-absolute top-50 end-50 carousel-caption p-2 p-md-3">
                                <h5 className="fw-bold text-white mx-2 mx-md-5 mb-3 mb-md-5 fs-1 fs-md-1 text-start">The Dark Knight</h5>
                                <Link to="/Movie" className="text-decoration-none d-block w-75 me-2 me-md-5">
                                    <button className="fw-bolder btn btn-danger w-100 py-1 py-md-2 fs-6 fs-md-5">More</button>
                                </Link>
                            </div>
                        </div>
                    </div>

                    <div className='header-play '>
                        <button className=" carousel-control-prev" type="button" data-bs-target="#carouselExampleControlsNoTouching" data-bs-slide="prev">
                            <span className="carousel-control-prev-icon" aria-hidden="true" />
                            <span className="visually-hidden">Previous</span>
                        </button>
                        <button className="carousel-control-next" type="button" data-bs-target="#carouselExampleControlsNoTouching" data-bs-slide="next">
                            <span className="carousel-control-next-icon" aria-hidden="true" />
                            <span className="visually-hidden">Next</span>
                        </button>
                    </div>
                </div>
            </header>
        </div>
    )
}

export default Header;
