import ReactDOM from 'react-dom/client';
import App from './App';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import { CartProvider } from 'react-use-cart'; 
import AllMovie from './Movies/AllMovie';
import AllFavorites from './Favorite/AllFavorites';
import AllStars from './Stars/AllStars';
import AllCrat from './Cart/AllCrat';
import AllLog from './Log/AllLog';
import AllContact from './Contact/AllContact';
import AllSingleProduct from './Singleproduct/AllSingleProduct';

var task = createBrowserRouter([
  {
    path: "/",
    element: <App />
  },
  {
    path: "/movie",
    element: <AllMovie />
  },
  {
    path: "/Favorites",
    element: <AllFavorites />
  },
  {
    path: "/Stars",
    element: <AllStars />
  },
  {
    path: "/Contact",
    element: <AllContact />
  },
  {
    path: "/bag",
    element: <AllCrat />
  },
  {
    path: "/login",
    element: <AllLog />
  },
  {
    path: "/SingleProduct/:id",
    element: <AllSingleProduct />
  },
])

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render( 

  <CartProvider>
    <RouterProvider router={task} />
  </CartProvider>
);
