import React from 'react'
import { Link } from 'react-router'

function Cinema() {
  return (
   <div>
        <div className='cinema-home'>
            
            <div className="container-lg">
                <div className="row">
                    <div className="col-md-6 text-light d-flex flex-column justify-content-center align-items-center  " >
                        <h2 className='fst-italic fw-bold lh-base mb-3'>Enjoy the world of CineSpot,<br/> Indulge in your favorite movies.</h2>
                        <p className='text-secondary fw-semibold fs-5'></p>
                    </div>
                    <div className="col-md-6 col-sm-12 d-flex justify-content-center mb-4 ">
                        <img src="/img/cinema1.jpe"  />
                    </div>

                    <div className="col-md-6 col-sm-12 d-flex justify-content-center mt-5 ">
                        <img src="/img/cinema2.jpe"  />
                    </div>

                    <div className="col-md-6 text-light d-flex flex-column justify-content-center align-items-center " >
                        <h2 className='cinema-book fst-italic lh-base fw-bolder  mb-3'>Book your ticket with us now !</h2>
                        <Link to="/movie" className='mt-2 btn btn-success fw-semibold fs-5'>Book Now</Link>
                    </div>
                </div>
            </div>

        </div>
    </div>
  )
}

export default Cinema