import React from 'react'
import { CartProvider, useCart } from 'react-use-cart' 
import Navbar from '../Components/Navbar';
import { Link } from 'react-router-dom';
import OtherHeader from '../Components/OtherHeader';

function Cart() {
    const { 
        isEmpty, 
        totalUniqueItems, 
        items, 
        updateItemQuantity, 
        removeItem, 
        cartTotal, 
        emptyCart 
    } = useCart();

    if (isEmpty) return (
        <div className="text-center mt-5">
            <h1 className=" text-light fw-bold">Your cart is empty ! 🛒</h1>
            <Link to="/movie" className="btn btn-danger btn-lg mt-3">Go Back to Movies</Link>
        </div>
    );

    return (
        <div className="container mt-5">
            <h2 className="text-center mb-5 fw-bold text-danger">🛒 Your Shopping Cart</h2>
            
            <div className="row">
                <div className="col-lg-8">
                    {items.map((item) => (
                        <div key={item.id} className="card mb-3 p-3 shadow-sm">
                            <div className="row g-0 align-items-center">
                                <div className="col-md-3">
                                    <img src={`/${item.img}`} className="img-fluid rounded-3" alt={item.title} style={{ height: "120px", objectFit: "cover" }} />
                                </div>
                                <div className="col-md-5 px-3">
                                    <h5 className="fw-bold">{item.title}</h5>
                                    <p className="text-danger fw-bold mb-0">Price per ticket: ${item.price}</p>
                                    <p className="text-success fw-semibold mt-1">Subtotal: ${item.price * item.quantity}</p>
                                </div>
                                <div className="col-md-2 d-flex align-items-center justify-content-center gap-2">
                                    <button 
                                        className="btn btn-sm btn-outline-secondary px-2"
                                        onClick={() => updateItemQuantity(item.id, item.quantity - 1)}
                                    >-</button>
                                    <span className="fs-5 fw-bold">{item.quantity}</span>
                                    <button 
                                        className="btn btn-sm btn-outline-secondary px-2"
                                        onClick={() => updateItemQuantity(item.id, item.quantity + 1)}
                                    >+</button>
                                </div>
                                <div className="col-md-2 text-end">
                                    <button 
                                        onClick={() => removeItem(item.id)} 
                                        className="btn btn-outline-danger btn-sm"
                                    >
                                        🗑 Remove
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                <div className="col-lg-4">
                    <div className="card p-4 shadow-sm bg-light">
                        <h4 className="fw-bold mb-4">Order Summary</h4>
                        <div className="d-flex justify-content-between mb-3 fs-5">
                            <span>Unique Items:</span>
                            <span className="fw-bold">{totalUniqueItems}</span>
                        </div>
                        <div className="d-flex justify-content-between mb-4 fs-4 border-top pt-3">
                            <span className="fw-bold">Total Price:</span>
                            <span className="fw-bold text-success">${cartTotal}</span>
                        </div>
                        <button 
                            onClick={() => {
                                alert(" Tickets booked successfully!");
                                emptyCart();
                            }} 
                            className="btn btn-success btn-lg w-100 fw-bold mb-2"
                        >
                            Checkout Now
                        </button>
                        <button 
                            onClick={() => emptyCart()} 
                            className="btn btn-outline-danger w-100 mb-2"
                        >
                            Clear Cart
                        </button>
                        <Link to="/movie" className="btn btn-outline-secondary w-100">Continue Shopping</Link>
                    </div>
                </div>
            </div>
        </div>
    )
}

function AllCrat() {
    return (
        <CartProvider>
            <Navbar/>
            <OtherHeader/>
            <Cart />
        </CartProvider>
    )
}

export default AllCrat;
