import React from 'react'
import Movies from '../Data/Movies.json'
import { Link, NavLink } from 'react-router-dom'

function Navbar() {
  return (

    <div>
      <nav className="nav-home navbar navbar-expand-md  py-0">
        <div className="container-fluid">
          <div className='row w-100 align-items-center g-3 g-md-0 m-0'>

            <div className="col-12 col-lg-4 d-flex justify-content-between align-items-center m-0">
              <NavLink className="nav-play navbar-brand fs-3 fst-italic fw-semibold m-0 text-light" to="/" >
                <img src="/img/logo1.png" alt="Logo" width={70} height={66} />
                CineSpot
              </NavLink>

              <button className="navbar-toggler bg-light " type="button" data-bs-toggle="collapse" data-bs-target="#navbarSupportedContent" aria-controls="navbarSupportedContent"
                aria-expanded="false" aria-label="Toggle navigation">
                <span className="navbar-toggler-icon "></span>
              </button>
            </div>

            <div className="collapse navbar-collapse nav-section col-12 col-md-4 justify-content-center p-0 mt-0 mb-1" id="navbarSupportedContent">

              <ul className="navbar-nav  nav-enjoy mb-2 d-md-flex flex-md-row text-center mt-3 mt-sm-0 gap-3 gap-md-0" style={{marginLeft:"60px"}}>
                <li className="nav-item  me-md-4 me-lg-5">
                  <NavLink className="nav-link  fs-5  fw-bold text-light enjoy-nav " aria-current="page" to="/"> Home </NavLink>
                </li>
                <li className="nav-item me-md-4 me-lg-5">
                  <NavLink className="enjoy-nav nav-link fs-5  fw-bold text-light " to="/movie">Movies</NavLink>
                </li>
                <li className="nav-item me-md-4 me-lg-5">
                  <NavLink className="enjoy-nav nav-link fs-5  fw-bold text-light " to="/Favorites">Favorites </NavLink>
                </li>
                <li className="nav-item me-md-5 me-lg-5">
                  <NavLink className="enjoy-nav nav-link fs-5  fw-bold text-light " to="/Stars">Stars</NavLink>
                </li>
                <li className="nav-item me-md-5 me-lg-5">
                  <NavLink className="enjoy-nav nav-link fs-5  fw-bold text-light " to="/Contact">ContactUs</NavLink>
                </li>
                
              </ul>
            </div>

            <div className="col-12  col-md-4 d-flex justify-content-center justify-content-md-end align-items-center gap-3 p-0 mb-2 mt-0 ">
              <Link to="/movie">
                <i className="nav-play fa-solid fa-magnifying-glass fs-4" style={{ color: "white" }}></i>
              </Link>
              <Link to="/bag">
                <i className="nav-play fa-solid fa-bag-shopping fs-4" style={{ color: "white" }}></i>
              </Link>
              <Link to="/login"  className="nav-play btn btn-secondary fw-bold px-3">Log In</Link>
            </div>

          </div>
        </div>
      </nav>
    </div>

  )
}

export default Navbar


