import React, { useState } from 'react';

function ContactUs() {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        subject: '',
        message: ''
    });
    const [isSent, setIsSent] = useState(false);

    const handleChange = (event) => {
        const { name, value } = event.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleSubmit = (event) => {
        
        
        setIsSent(true);
        
        setFormData({ name: '', email: '', subject: '', message: '' });
        
        setTimeout(() => setIsSent(false), 4000);
        event.preventDefault();
    };

    return (
        <div className="container my-5" style={{ minHeight: '80vh', color: '#fff' }}>
            <div className="row justify-content-center">
                <div className="col-lg-8">

                    <div className="text-center mb-5">
                        <h2 className="fw-bold fst-italic text-success ">Contact Us</h2>
                        <p className='fs-5'>Have any questions or feedback about CineSpot? We'd love to hear from you!</p>
                    </div>

                    <div className="row g-4">
                        <div className="col-md-5 bg-dark p-4 rounded shadow-sm d-flex flex-column justify-content-center">
                            <h4 className="fw-bold mb-4 text-success">Get in Touch</h4>

                            <div className="mb-3 d-flex align-items-center">
                                <div>
                                    <h6 className="mb-0 fw-bold">Our Location</h6>
                                    <small className="text-secondary"> Egypt</small>
                                </div>
                            </div>

                            <div className="mb-3 d-flex align-items-center">
                                <div>
                                    <h6 className="mb-0 fw-bold">Email Address</h6>
                                    <small className="text-secondary">user@gmail.com</small>
                                </div>
                            </div>

                            <div className="d-flex align-items-center">
                                <div>
                                    <h6 className="mb-0 fw-bold">Phone Number</h6>
                                    <small className="text-secondary">+20 11111111111</small>
                                </div>
                            </div>
                        </div>

                        <div className="col-md-7 p-4 bg-dark rounded shadow-sm">
                            {isSent && (
                                <div className="alert alert-success fw-bold text-center animate__animated animate__fadeIn" role="alert">
                                     Thank you! Your message has been sent successfully.
                                </div>
                            )}

                            <form onSubmit={handleSubmit}>
                                <div className="mb-3">
                                    <label className="mb-2 fw-semibold">Your Name</label>
                                    <input
                                        type="text"
                                        className="form-control border-0"
                                        name="name"
                                        value={formData.name}
                                        onChange={handleChange}
                                        required
                                    />
                                </div>

                                <div className="mb-3">
                                    <label className="mb-2 fw-semibold">Email Address</label>
                                    <input
                                        type="email"
                                        className="form-control border-0"
                                        name="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        required
                                    />
                                </div>

                                <div className="mb-3">
                                    <label className="mb-2 fw-semibold">Subject</label>
                                    <input
                                        type="text"
                                        className="form-control border-0"
                                        name="subject"
                                        value={formData.subject}
                                        onChange={handleChange}
                                        required
                                    />
                                </div>

                                <div className="mb-4">
                                    <label className="mb-2 fw-semibold">Message</label>
                                    <textarea
                                        className="form-control  border-0"
                                        rows="4"
                                        name="message"
                                        value={formData.message}
                                        onChange={handleChange}
                                        required
                                    ></textarea>
                                </div>

                                <button type="submit" className="btn btn-success fw-bold w-100 py-2">
                                    Send Message
                                </button>
                            </form>
                        </div>
                    </div>

                </div>
            </div>
        </div>
    );
}

export default ContactUs;
