

import React from 'react'
import { Link } from 'react-router'

function Footer() {
  return (
    <footer className="footer-home text-light pt-5 pb-3">
      <div className="container-fluid">
        <div className="row g-4 ">

          <div className=" col-md-6 d-flex flex-column align-items-center justify-content-center">
            <Link className="navbar-brand me-5 fs-1 fst-italic fw-bolder  text-light" to="/">
              <img src="/img/logo1.png" alt="Logo" width={210} height={200} /> CineSpot</Link>
            <p className="text-bold fs-4  " style={{ maxWidth: "530px" }}>
              Welcome to CineSpot, your ultimate destination for endless movie magic.
              Dive into a cinematic universe where you can stream exclusive content,
              rate your favorites, and explore the best of world cinema. Enjoy the world
              of CineSpot with us and indulge in everything you love, from blockbuster hits
              to hidden gems. Your next cinematic adventure starts here.            </p>
          </div>
          <div className="footer-play col-md-6 d-flex align-items-center justify-content-center">
            <img src="img/cinema3.jpe" alt="" />

          </div>

        </div>

        <hr className="border-secondary my-5 opacity-25" />
        <div className="text-center text-secondary small">
          &copy; {new Date().getFullYear()} <span className="text-light fw-semibold">CineSpot</span>
        </div>
        
      </div>
    </footer>
  )
}

export default Footer


