import React from 'react'
import { Link } from 'react-router'

function Main() {
    return (
        <div >
            <main className="main-home container-fluid px-md-5 ">
                <div className="row align-items-center  m-0 w-100 h-100 g-5">

                    <div className="col-12 col-lg-6 ">

                        <div id="heroMovieCarousel" className="carousel slide carousel-fade main-enjoy"
                            data-bs-ride="carousel" data-bs-interval="5000" data-bs-pause="false">

                            <div className="carousel-inner">
                                <div className="carousel-item">
                                    <div className="main-play">
                                        <img src="/img/carousel6.jpe" className="img-left" alt="Movie 1" />
                                        <img src="/img/carousel7.jpe" className="img-center" alt="Movie 2" />
                                        <img src="/img/carousel8.jpe" className="img-right" alt="Movie 3" />
                                        <img src="/img/carousel9.jpe" className="img-footer" alt="Movie 4" />
                                    </div>
                                </div>

                                <div className="carousel-item">
                                    <div className="main-play">
                                        <img src="/img/carousel7.jpe" className="img-left" alt="Movie 2" />
                                        <img src="/img/carousel8.jpe" className="img-center" alt="Movie 3" />
                                        <img src="/img/carousel9.jpe" className="img-right" alt="Movie 4" />
                                        <img src="/img/carousel6.jpe" className="img-footer" alt="Movie 1" />
                                    </div>
                                </div>

                                <div className="carousel-item active">
                                    <div className="main-play">
                                        <img src="/img/carousel8.jpe" className="img-left" alt="Movie 3" />
                                        <img src="/img/carousel9.jpe" className="img-center" alt="Movie 4" />
                                        <img src="/img/carousel6.jpe" className="img-right" alt="Movie 1" />
                                        <img src="/img/carousel7.jpe" className="img-footer" alt="Movie 2" />
                                    </div>
                                </div>

                                <div className="carousel-item">
                                    <div className="main-play">
                                        <img src="/img/carousel9.jpe" className="img-left" alt="Movie 4" />
                                        <img src="/img/carousel6.jpe" className="img-center" alt="Movie 1" />
                                        <img src="/img/carousel7.jpe" className="img-right" alt="Movie 2" />
                                        <img src="/img/carousel8.jpe" className="img-footer" alt="Movie 3" />
                                    </div>
                                </div>

                            </div>

                            <button className=" carousel-control-prev custom-nav-btn" type="button" data-bs-target="#heroMovieCarousel" data-bs-slide="prev">
                                <span className="carousel-control-prev-icon" aria-hidden="true" />
                                <span className="visually-hidden">Previous</span>
                            </button>
                            <button className="carousel-control-next custom-nav-btn" type="button" data-bs-target="#heroMovieCarousel" data-bs-slide="next">
                                <span className="carousel-control-next-icon" aria-hidden="true" />
                                <span className="visually-hidden">Next</span>
                            </button>

                        </div>
                    </div>

                    <div className="col-12 col-lg-6 text-center text-lg-start ps-lg-5 order-2 order-lg-2 mt-4 mt-lg-0">
                        <h2 className="display-4 fw-bold mb-3  hero-title text-light">
                            Dive Into The World <br /> Of Endless CineSpot
                        </h2>
                        <p className="fs-5 text-secondary mb-4 hero-subtitle">
                            Stream your favorite movies, exclusive blockbusters, and award-winning series anytime, anywhere. Your ticket to ultimate entertainment starts here.
                        </p>
                        <div className="d-flex flex-column flex-lg-row gap-3 justify-content-center justify-content-lg-start">
                            
                            <Link to="/Movie"  className="btn btn-outline-light btn-lg px-4 py-2 fw-semibold rounded-pill">
                                Explore Movies
                            </Link>
                        </div>
                    </div>

                </div>

            </main>
        </div>

    )
}

export default Main
